package io.knowledgebrain.content;
import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.flywaydb.core.Flyway;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;
import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_CONTENT_DATABASE_URL",matches=".+")
class AttachmentStoreIntegrationTest {
 PGSimpleDataSource source;NoteStore store;JdbcTemplate jdbc;UuidV7 ids=new UuidV7(Clock.systemUTC());String trace="d".repeat(32);
 @BeforeEach void setup(){source=new PGSimpleDataSource();source.setURL(System.getenv("BRAIN_TEST_CONTENT_DATABASE_URL"));source.setUser("brain_content");source.setPassword(System.getenv("BRAIN_TEST_CONTENT_DATABASE_PASSWORD"));Flyway.configure().dataSource(source).locations("classpath:db/migration").load().migrate();store=new NoteStore(source,Clock.systemUTC());jdbc=new JdbcTemplate(source);}
 MediaAvailabilityClient.File file(UUID space){return new MediaAvailabilityClient.File(ids.next(),space,"AVAILABLE",2,"test.pdf","application/pdf",10,"a".repeat(64),Instant.now(),Instant.now());}
 @Test void stableRelationsIndependentVersionsHistoryRetirementAndIsolation(){UUID space=ids.next(),actor=ids.next();var note=store.create(space,actor,"a","",trace);var a=file(space);var b=file(space);assertThat(store.attachments(space,note.noteId()).attachmentVersion()).isZero();var first=store.attachments(space,note.noteId(),actor,0,List.of(a,b),trace);var reordered=store.attachments(space,note.noteId(),actor,1,List.of(b,a),trace);assertThat(reordered.items().getLast().attachmentId()).isEqualTo(first.items().getFirst().attachmentId());store.change(space,note.noteId(),actor,1,"new","body",false,trace);assertThat(store.attachments(space,note.noteId())).isEqualTo(reordered);store=new NoteStore(source,Clock.systemUTC());assertThat(store.attachmentHistory(space,note.noteId(),100,10).getFirst().snapshot()).isEqualTo(reordered);assertThatThrownBy(()->store.attachments(ids.next(),note.noteId())).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->store.attachments(space,note.noteId(),actor,2,List.of(file(ids.next())),trace)).isInstanceOf(ResponseStatusException.class);assertThat(store.attachments(space,note.noteId())).isEqualTo(reordered);store.change(space,note.noteId(),actor,2,null,null,true,trace);var history=store.attachmentHistory(space,note.noteId(),100,10);assertThat(history).hasSize(3);assertThat(history.getFirst().snapshot().items()).isEmpty();assertThat(history.getLast().snapshot()).isEqualTo(first);}
 @Test void outboxFailureRollsBackRelationAndHistory(){UUID space=ids.next(),actor=ids.next();var note=store.create(space,actor,"a","",trace);var first=store.attachments(space,note.noteId(),actor,0,List.of(file(space)),trace);jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT attachment_test_rollback CHECK(trace_id <> 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb') NOT VALID");try{assertThatThrownBy(()->store.attachments(space,note.noteId(),actor,1,List.of(),"b".repeat(32))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(store.attachments(space,note.noteId())).isEqualTo(first);assertThat(store.attachmentHistory(space,note.noteId(),100,10)).hasSize(1);}finally{jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT attachment_test_rollback");}}
 @Test void concurrentChangesHaveOneWinner() throws Exception {UUID space=ids.next(),actor=ids.next();var note=store.create(space,actor,"a","",trace);var files=List.of(file(space));try(var workers=Executors.newVirtualThreadPerTaskExecutor()){var start=new CountDownLatch(1);var futures=new ArrayList<Future<Integer>>();for(int n=0;n<4;n++)futures.add(workers.submit(()->{start.await();try{store.attachments(space,note.noteId(),actor,0,files,trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var codes=new ArrayList<Integer>();for(var f:futures)codes.add(f.get(30,TimeUnit.SECONDS));assertThat(Collections.frequency(codes,200)).isEqualTo(1);assertThat(codes).containsOnly(200,412);}assertThat(store.attachmentHistory(space,note.noteId(),100,10)).hasSize(1);}
}
